<?php
/**
 * ChatHelp — apply-pwa-twa (CH_PWA) — App'te mikrofon icin BEDAVA cozum altyapisi.
 *  Siteyi "yuklenebilir uygulama" (PWA) yapar; boylece PWABuilder ile UCRETSIZ
 *  bir TWA (Trusted Web Activity) paketlenebilir. TWA App icinde CHROME motorunu
 *  kullanir -> mikrofon (SpeechRecognition/getUserMedia) tıpkı sitedeki gibi
 *  OTOMATIK calisir; WebView izin sorunu tamamen ortadan kalkar.
 *  BU BETIK sunucuya sunlari yazar:
 *   [1] manifest.json  (standalone app, lacivert tema, CH ikonlari)
 *   [2] sw.js          (minimal service worker — PWA "yuklenebilir" olur)
 *   [3] icon-192.png + icon-512.png (PWA ikonlari, gomulu base64)
 *   [4] index.php <head>'e: <link rel=manifest> + theme-color + apple-web-app
 *       meta'lari + sw.js kaydi (service worker register)
 *  Idempotent; lint + .bak + dogrulama.
 * KULLANIM: pull2.php?key=...&files=apply-pwa-twa.php
 */
header('Content-Type: text/plain; charset=UTF-8');
error_reporting(E_ERROR | E_PARSE);
echo "apply-pwa-twa BASLADI OK (PHP ".PHP_VERSION.")\n\n";
$D=__DIR__;

/* ── [3] ikonlar ── */
$png192=base64_decode(<<<'B64'

B64
);
$png512=base64_decode(<<<'B64'

B64
);
$w=@file_put_contents("$D/icon-192.png",$png192);
echo ($w&&$w>100)?"  ✓ [3] icon-192.png yazildi ($w B)\n":"  ✗ [3] icon-192.png\n";
$w=@file_put_contents("$D/icon-512.png",$png512);
echo ($w&&$w>100)?"  ✓ [3] icon-512.png yazildi ($w B)\n":"  ✗ [3] icon-512.png\n";

/* ── [1] manifest.json ── */
$manifest = '{
  "name": "ChatHelp",
  "short_name": "ChatHelp",
  "description": "Rechtsdokumente & Visa per KI",
  "start_url": "/chat/",
  "scope": "/chat/",
  "display": "standalone",
  "orientation": "portrait",
  "background_color": "#0a102a",
  "theme_color": "#0a102a",
  "lang": "de",
  "dir": "ltr",
  "icons": [
    { "src": "/chat/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any" },
    { "src": "/chat/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any" },
    { "src": "/chat/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "maskable" },
    { "src": "/chat/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable" }
  ]
}';
$w=@file_put_contents("$D/manifest.json",$manifest);
echo ($w!==false)?"  ✓ [1] manifest.json yazildi ($w B)\n":"  ✗ [1] manifest.json\n";

/* ── [2] sw.js (minimal, network-first) ── */
$sw = "/* ChatHelp service worker — PWA yuklenebilirlik icin minimal */\n"
    . "self.addEventListener('install', function(e){ self.skipWaiting(); });\n"
    . "self.addEventListener('activate', function(e){ e.waitUntil(self.clients.claim()); });\n"
    . "self.addEventListener('fetch', function(e){\n"
    . "  e.respondWith(fetch(e.request).catch(function(){ return caches.match(e.request); }));\n"
    . "});\n";
$w=@file_put_contents("$D/sw.js",$sw);
echo ($w!==false)?"  ✓ [2] sw.js yazildi ($w B)\n":"  ✗ [2] sw.js\n";

/* ── [4] index.php <head> + SW kaydi ── */
$file="$D/index.php";
$src=@file_get_contents($file);
if($src===false) exit("\nindex.php okunamadi\n");
if(strpos($src,'CH_PWA')!==false){ echo "\n  ✓ [4] index.php zaten PWA-baglantili (atlandi)\n\n✓ Tekrar calistirildi: dosyalar guncel.\n"; exit; }

$fail=[];
$o1='<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">';
$n1=$o1."\n<!--CH_PWA-->\n"
  .'<link rel="manifest" href="/chat/manifest.json">'."\n"
  .'<meta name="theme-color" content="#0a102a">'."\n"
  .'<meta name="mobile-web-app-capable" content="yes">'."\n"
  .'<meta name="apple-mobile-web-app-capable" content="yes">'."\n"
  .'<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">'."\n"
  .'<meta name="apple-mobile-web-app-title" content="ChatHelp">';
$c=substr_count($src,$o1);
if($c!==1){ echo "  ✗ [4a] viewport anchor ($c)\n"; $fail[]='4a'; }
else { $src=str_replace($o1,$n1,$src); echo "  ✓ [4a] <head>'e manifest + theme-color + apple-web-app meta'lari eklendi\n"; }

$swreg='<script id="ch-pwa-sw">/*CH_PWA*/try{if("serviceWorker" in navigator){window.addEventListener("load",function(){navigator.serviceWorker.register("/chat/sw.js").catch(function(){});});}}catch(e){}</script>';
$pos=strripos($src,'</body>');
if($pos===false){ echo "  ✗ [4b] </body> yok\n"; $fail[]='4b'; }
else { $src=substr($src,0,$pos).$swreg."\n".substr($src,$pos); echo "  ✓ [4b] service worker kaydi eklendi\n"; }

if($fail){ echo "\nHATA: eslesmeyen: ".implode(', ',$fail)." — index DEGISTIRILMEDI (ama manifest/sw/ikonlar yazildi, zararsiz).\n"; exit; }

$tmp=tempnam(sys_get_temp_dir(),'pw').'.php';
file_put_contents($tmp,$src);
$lo=[];$rc=0; exec('php -l '.escapeshellarg($tmp).' 2>&1',$lo,$rc); @unlink($tmp);
if($rc!==0){ echo "\nLINT HATASI — index DEGISTIRILMEDI:\n  ".implode("\n  ",$lo)."\n"; exit; }
@file_put_contents($file.'.bak-pwa-'.date('Ymd-His'),(string)@file_get_contents($file));
$w=@file_put_contents($file,$src);
if($w===false||$w<strlen($src)){ echo "\n✗ YAZMA HATASI.\n"; exit; }
$chk=(string)@file_get_contents($file);
if(strpos($chk,'CH_PWA')===false){ echo "\n✗ DOGRULAMA BASARISIZ.\n"; exit; }
echo "  ✓ DOGRULAMA: CH_PWA + manifest + sw diskte (index ".strlen($chk)." B)\n";
echo "\n✓ Site artik YUKLENEBILIR PWA. Sonraki adim (ucretsiz):\n";
echo "   1) pwabuilder.com -> https://chat-help.com/chat/ adresini gir -> 'Start'\n";
echo "   2) Android -> 'Generate Package' -> .aab indir (TWA)\n";
echo "   3) Google Play Console'a yeni surum olarak yukle\n";
echo "   TWA Chrome motoru kullanir -> App'te MIKROFON otomatik calisir.\n";
echo "   NOT: PWABuilder sana bir assetlinks.json + SHA256 verir; onu\n";
echo "   /.well-known/assetlinks.json'a koymak icin ayrica yardim ederim.\n";
